:root {
  --sand: #f5e9d0;
  --ocean: #1a7fa0;
  --ocean-light: #d0edf5;
  --coral: #e8603c;
  --ink: #1c2b36;
  --muted: #6b8a96;
  --white: #ffffff;
  --divider: #c8dde5;
  --green: #2e9e6b;
}

.receipt {
  background: var(--white);
  border: 2px solid var(--ocean);
  border-radius: 14px;
  width: 400px;
  overflow: hidden;
  font-size: 13px;
  color: var(--ink);
}

.receipt-header {
  background: var(--ocean);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
}

.shop-icon {
  font-size: 22px;
  line-height: 1;
}

.shop-info {
  flex: 1;
}

.shop-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--white);
  margin: 0;
  line-height: 1.2;
}

.shop-sub {
  font-size: 10px;
  color: var(--ocean-light);
  margin: 0;
}

.receipt-badge {
  background: var(--coral);
  color: var(--white);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
  padding: 3px 7px;
  border-radius: 5px;
}

.rental-item {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--sand);
  padding: 10px 14px;
  border-bottom: 1px solid var(--divider);
}

.item-icon {
  font-size: 20px;
  line-height: 1;
}

.item-details {
  flex: 1;
}

.item-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--ink);
  margin: 0 0 2px 0;
}

.item-meta {
  font-size: 10px;
  color: var(--muted);
  margin: 0;
}

.item-price {
  font-size: 20px;
  font-weight: 700;
  color: var(--ocean);
}

.price-unit {
  font-size: 11px;
  font-weight: 400;
  color: var(--muted);
}

.extras-list {
  list-style: none;
  margin: 0;
  padding: 8px 14px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  border-bottom: 1px dashed var(--divider);
}

.extra-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.extra-label {
  font-size: 12px;
  color: var(--ink);
}

.extra-dot {
  flex: 1;
  border-bottom: 1px dotted var(--divider);
}

.extra-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--ink);
}

.receipt-footer {
  padding: 8px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.footer-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-label {
  font-size: 12px;
  color: var(--muted);
}

.footer-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--ink);
}

.total-row {
  background: var(--ocean-light);
  border-radius: 7px;
  padding: 6px 10px;
}

.total-amount {
  font-size: 18px;
  font-weight: 700;
  color: var(--coral);
}

.status-pill {
  background: var(--green);
  color: var(--white);
  font-size: 10px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 20px;
}

.footer-date {
  font-size: 11px;
  color: var(--muted);
}
